import { render } from '@testing-library/react'
import type { GetServerSideProps } from 'next'
import { ResultCard } from '@/components/ResultCard'
import type { SearchResponse } from '@/search/engine'
import { isSearchDocument, parseDocuments } from '@/search/validate'
import { KIND_LABEL, KIND_PATH, type SearchDocument } from '@/types/document'
import rawDocuments from '../data/documents.json'

/**
 * Checks for exercise 1 (doctrine in the search). Do not edit this file: run
 * `npm run verify:class-1`. Each test name starts with its step.
 *
 * The file is written so it compiles before and after the exercise: it reads
 * doctrine through plain strings, not through the `Doctrine` type you create.
 */

process.env.SEARCH_LATENCY_MS = '0'

const labels: Record<string, string> = KIND_LABEL
const paths: Record<string, string> = KIND_PATH
const isDoctrine = (document: { kind: string }) => document.kind === 'doctrine'
const doctrineInDatabase = (rawDocuments as { kind: string }[]).filter(isDoctrine)
const sample = doctrineInDatabase[0] as unknown as SearchDocument & Record<string, unknown>

describe('exercise 1: doctrine in the search', () => {
  it('step 2: the doctrine label is "Doutrina" and its route is /doutrina/busca', () => {
    expect(labels.doctrine).toBe('Doutrina')
    expect(paths.doctrine).toBe('/doutrina/busca')
  })

  it('step 2: the validation accepts the 16 doctrine documents and rejects one without edition', () => {
    expect(parseDocuments(rawDocuments as unknown).filter(isDoctrine)).toHaveLength(16)
    expect(isSearchDocument({ ...sample, edition: undefined })).toBe(false)
  })

  it('step 3: the doctrine card shows the work, the author, the publisher and the edition', () => {
    const { container } = render(<ResultCard document={sample} query="" />)

    expect(container.textContent).toContain(String(sample.work))
    expect(container.textContent).toContain(String(sample.author))
    expect(container.textContent).toContain(String(sample.publisher))
    expect(container.textContent).toContain(`${String(sample.edition)}ª ed.`)
  })

  it('step 4: /doutrina/busca renders only doctrine, on the server', async () => {
    // A variable path, so this file compiles before the route exists.
    const route = '../pages/doutrina/busca'
    const page = (await import(route)) as { getServerSideProps: GetServerSideProps<{ response: SearchResponse }> }
    const context = { query: { q: 'usucapiao' }, resolvedUrl: '/doutrina/busca?q=usucapiao', res: { statusCode: 200 } }

    const result = await page.getServerSideProps(context as never)

    expect(result).toHaveProperty('props')
    const { response } = (result as { props: { response: SearchResponse } }).props
    expect(response.total).toBe(2)
    expect(response.items.every(isDoctrine)).toBe(true)
  })
})
